impl Solution {
    pub fn lost_permutation(b: Vec<u32>, m: usize, s: u32) -> bool {
        let mut present = [false; 51];
        let mut sum = 0u32;
        let mut max_num = 0u32;

        for &num in &b {
            if num > 50 {
                return false;
            }
            if present[num as usize] {
                return false;
            }
            present[num as usize] = true;
            sum += num;
            if num > max_num {
                max_num = num;
            }
        }

        let n = max_num as usize;
        let total_sum = (n * (n + 1)) / 2;
        let missing_sum = total_sum - sum;

        if missing_sum == s {
            return true;
        }

        if missing_sum < s {
            return false;
        }

        let remaining = s - missing_sum;
        let mut next_num = max_num + 1;
        while remaining > 0 && next_num <= 50 {
            if !present[next_num as usize] {
                if remaining >= next_num {
                    remaining -= next_num;
                    present[next_num as usize] = true;
                } else {
                    return false;
                }
            }
            next_num += 1;
        }

        remaining == 0
    }
}
